    + (textureSampleLevel(src, samp, uv + vec2f(o, 0.0), 0.0).r
     + textureSampleLevel(src, samp, uv - vec2f(o, 0.0), 0.0).r
     + textureSampleLevel(src, samp, uv + vec2f(0.0, o), 0.0).r
     + textureSampleLevel(src, samp, uv - vec2f(0.0, o), 0.0).r) * 0.14;
